const names = ['N','NNE','NE','ENE','E','ESE','SE','SSE','S','SSW','SW','WSW','W','WNW','NW','NNW'];
const a = msg.payload.acceleration;
const h = msg.payload.heading;
const name = names[Math.floor((h + 11.25) / 22.5) % 16];
const pitch = Math.atan2(-a.x, Math.sqrt(a.y*a.y + a.z*a.z)) * 180 / Math.PI;
const roll = Math.atan2(a.y, a.z) * 180 / Math.PI;
msg.payload = { acceleration: a, magnetic: msg.payload.magnetic, heading: h, heading_name: name, pitch, roll, temperature_delta: msg.payload.temperature_delta };
return msg;
